:root{--red:#f54235;--bg:#101114;--panel:#1a1b1e;--muted:#777a80;--line:#303135;--white:#f5f4f1}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:var(--bg);color:var(--white);font-family:Barlow,Arial,sans-serif}button{font:inherit;cursor:pointer}button:focus-visible{outline:2px solid #fff;outline-offset:3px}.app{display:flex;min-height:100vh}.sidebar{width:205px;flex-shrink:0;border-right:1px solid #2a2b2e;background:#121316;padding:31px 18px;display:flex;flex-direction:column}.brand{display:flex;align-items:flex-start;color:white;text-decoration:none;font:900 italic 22px/1 'Barlow Condensed',sans-serif;letter-spacing:-.7px}.brand>span:nth-child(2)>span{color:var(--red)}.brand small{display:block;color:#777;font:700 8px Barlow,sans-serif;letter-spacing:3.1px;margin-top:6px}.brand-mark{font:900 italic 29px/20px 'Barlow Condensed';color:var(--red);margin-right:8px;letter-spacing:-5px;padding-right:4px}.side-label{font-size:9px;letter-spacing:1.6px;color:#686a6f;font-weight:800;margin:66px 11px 16px}.nav{display:grid;gap:7px}.nav-item{border:0;background:transparent;color:#929397;text-align:left;padding:14px 12px;font-size:12px;font-weight:700;display:flex;align-items:center;gap:13px;width:100%}.nav-item.active{color:#fff;background:#252326;border-left:2px solid var(--red);padding-left:10px}.nav-icon{font-size:17px;width:18px;color:#8b8b8c}.nav-item.active .nav-icon{color:var(--red)}.nav-arrow{margin-left:auto;color:#777;font-size:18px}.side-bottom{margin-top:auto;padding:20px 10px 0}.side-online{font-size:9px;letter-spacing:1px;color:#85878a;font-weight:700}.side-online i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#71bd83;margin-right:6px}.side-version{border-top:1px solid #2b2c2f;margin-top:17px;padding-top:16px;font:700 11px 'Barlow Condensed';letter-spacing:1px;color:#a8a8a8}.side-version span{float:right;color:#5a5a5c}.main-wrap{min-width:0;flex:1}.topbar{height:74px;border-bottom:1px solid #2a2b2e;display:flex;align-items:center;justify-content:space-between;padding:0 40px}.breadcrumb{font-size:10px;letter-spacing:1.4px;color:#77797e;font-weight:700}.breadcrumb span{color:#444;margin:0 11px}.breadcrumb strong{color:#e4e4e4}.top-right{display:flex;align-items:center;gap:14px}.edition{font-size:9px;color:#888b90;letter-spacing:1.5px;font-weight:700}.divider{height:27px;border-left:1px solid #333;margin:0 5px}.profile-icon{background:#292a2d;color:#ddd;width:33px;height:33px;display:grid;place-items:center}.profile{font-size:10px;font-weight:800;letter-spacing:.5px}.profile small{display:block;font-size:8px;letter-spacing:1px;color:#777;margin-top:4px}.content{max-width:1600px;margin:auto;padding:30px 40px 0}.page-heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:23px}.eyebrow{font-size:9px;letter-spacing:1.8px;font-weight:800;color:#e5e5e5}.eyebrow>span{display:inline-block;width:17px;height:3px;background:var(--red);vertical-align:middle;margin-right:8px}.muted{color:#85878b}.page-heading h1,.modal-header h2{font:900 italic 42px/.95 'Barlow Condensed',sans-serif;margin:12px 0 8px;letter-spacing:.3px}.page-heading h1 em,.section-title h3 em,.setup h3 em,.modal h2 em{font-style:italic;color:var(--red)}.page-heading p,.modal-header p{margin:0;color:#8f9196;font-size:12px}.heading-index{font:700 21px 'Barlow Condensed';color:#ddd}.heading-index span{color:#58595d;font-size:14px}.dashboard{display:grid;grid-template-columns:minmax(0,1fr) 315px;gap:20px}.hero{height:352px;position:relative;overflow:hidden;background:#262b2c}.hero-image{position:absolute;inset:0;background:url('assets/hero.jpg') center 53%/cover}.hero-shade{position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,10,12,.94) 0%,rgba(9,10,12,.77) 28%,rgba(9,10,12,.15) 70%),linear-gradient(0deg,rgba(8,9,10,.5),transparent 40%)}.hero-content{position:absolute;left:34px;top:31px}.hero-kicker{font-size:9px;font-weight:800;letter-spacing:2px;color:#e2e2e2}.hero-kicker span{color:var(--red);margin-right:7px}.hero h2{font:900 italic clamp(45px,5.1vw,76px)/.86 'Barlow Condensed';letter-spacing:-1px;margin:27px 0 17px;text-shadow:0 2px 15px #0005}.hero h2 em{color:var(--red);font-style:italic}.hero p{font-size:12px;line-height:1.6;color:#d0d0d0}.hero-bottom{font-size:9px;letter-spacing:1.3px;font-weight:800;margin-top:29px;color:#e1e1e1}.red-line{display:inline-block;vertical-align:middle;width:25px;height:2px;background:var(--red);margin-right:9px}.hero-tag{position:absolute;right:22px;bottom:22px;display:flex;align-items:center;gap:9px;color:#fff}.hero-tag b{font:800 italic 38px 'Barlow Condensed';color:var(--red)}.hero-tag span{font-size:8px;letter-spacing:1px;line-height:1.2;font-weight:800}.destinations{margin-top:27px}.section-title{display:flex;align-items:end;justify-content:space-between;margin-bottom:14px}.section-title h3,.setup h3{font:800 italic 24px/1 'Barlow Condensed';margin:7px 0 0}.text-button,.change{border:0;background:transparent;color:#d5d5d5;font-size:9px;font-weight:800;letter-spacing:.8px;padding:5px 0}.text-button span,.change{color:var(--red)}.location-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.location-card{border:1px solid transparent;position:relative;height:122px;overflow:hidden;text-align:left;background:#26292c;color:white;padding:0}.location-card.active{border-color:var(--red)}.location-card:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(0,0,0,.91),transparent 100%)}.location-card img{width:100%;height:100%;object-fit:cover;transition:transform .3s}.location-card:hover img{transform:scale(1.07)}.location-info{position:absolute;z-index:1;bottom:12px;left:13px}.location-info small{display:block;font-size:8px;letter-spacing:1.3px;font-weight:700;color:#d0d0d0}.location-info strong{display:block;font:800 italic 22px 'Barlow Condensed';margin-top:2px}.location-check{position:absolute;z-index:1;right:10px;top:10px;background:var(--red);font-size:10px;padding:4px 6px}.setup{background:#1b1c1f;border:1px solid #303135;padding:22px 22px 15px}.setup-top{display:flex;justify-content:space-between;align-items:flex-end}.setup-num{color:#66676b;font:700 11px 'Barlow Condensed';letter-spacing:1px}.setup-line{height:2px;background:linear-gradient(90deg,var(--red) 42px,#37383b 42px);margin:19px 0}.setup-section{margin-bottom:20px}.setup-label{display:flex;justify-content:space-between;align-items:center;color:#8a8b8e;font-size:9px;letter-spacing:1px;font-weight:800}.change{font-size:9px}.selected-location{display:flex;align-items:center;gap:12px;margin-top:12px}.pin{background:#292a2d;width:38px;height:38px;display:grid;place-items:center;color:var(--red);font-size:24px}.selected-location strong{display:block;font:800 italic 20px/1 'Barlow Condensed'}.selected-location small{font-size:9px;letter-spacing:1px;color:#898b90;font-weight:700}.selected-flag{margin-left:auto;font-size:20px}.car-section{border-top:1px solid #343539;padding-top:17px}.car-image{height:106px;background:linear-gradient(0deg,#18191b 0%,transparent 55%),url('assets/car.jpg') center 57%/cover;margin-top:10px;position:relative}.car-class{position:absolute;left:8px;top:8px;background:#242427;color:#e4e4e4;font-size:8px;font-weight:800;letter-spacing:1px;padding:5px 7px}.car-name{font:800 italic 22px 'Barlow Condensed';margin-top:4px}.car-sub{font-size:8px;letter-spacing:1px;font-weight:700;color:#808287}.car-sub span{float:right;letter-spacing:2px;color:var(--red)}.stat{display:flex;align-items:center;gap:9px;font-size:8px;font-weight:800;color:#85878a;letter-spacing:.8px;margin-top:13px}.stat>span{width:59px}.stat div{height:3px;flex:1;background:#3b3c3e}.stat i{display:block;height:100%;background:var(--red)}.stat b{color:#e6e6e6;font-size:10px}.race-meta{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid #343539;padding-top:15px;margin-top:8px;margin-bottom:18px}.race-meta span{display:block;font-size:8px;color:#808287;letter-spacing:1px;font-weight:800}.race-meta strong{font:800 13px 'Barlow Condensed';letter-spacing:.4px}.start-button{width:100%;border:0;background:var(--red);color:white;padding:15px 17px;display:flex;justify-content:space-between;align-items:center;text-align:left;font:800 italic 17px 'Barlow Condensed';letter-spacing:.8px;transition:background .2s}.start-button:hover{background:#ff584b}.start-button b{font:400 20px Barlow}.setup-foot{font-size:8px;letter-spacing:1px;color:#6d6f73;font-weight:800;margin-top:13px}.setup-foot span{float:right;color:#f54235;letter-spacing:-1px}footer{display:flex;justify-content:space-between;padding:24px 0;color:#65666a;font-size:8px;font-weight:700;letter-spacing:1.2px}footer b{color:var(--red);margin-left:8px}.hidden{display:none!important}
.modal{position:fixed;inset:0;z-index:20;background:#07080bdc;display:grid;place-items:center;padding:20px}.modal-panel{width:min(980px,100%);max-height:min(760px,90vh);overflow:auto;background:#1a1b1e;border:1px solid #414246;padding:30px}.modal-header{display:flex;justify-content:space-between}.modal-header h2{font-size:36px}.close-modal{align-self:flex-start;border:1px solid #46474a;background:#26272a;color:white;font-size:26px;width:38px;height:38px;line-height:1}.modal-filters{display:flex;flex-wrap:wrap;gap:8px;margin:25px 0 16px}.filter{border:1px solid #3b3c40;background:#242528;color:#999;padding:9px 14px;font-size:10px;letter-spacing:.7px;font-weight:800}.filter.active{background:var(--red);border-color:var(--red);color:white}.modal-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.choice{position:relative;text-align:left;background:#242528;border:1px solid #38393c;color:white;min-height:85px;padding:15px;transition:border-color .2s}.choice:hover,.choice.selected{border-color:var(--red)}.choice.selected:after{content:'✓';position:absolute;top:10px;right:10px;color:var(--red)}.choice small{display:block;color:#909196;font-size:9px;letter-spacing:1px;font-weight:800;margin-bottom:7px}.choice strong{font:800 italic 19px/1 'Barlow Condensed'}.choice .choice-flag{float:right;font-size:20px;margin-top:14px}.choice .choice-stats{display:block;margin-top:8px;color:#8d8e92;font-size:9px;font-weight:700;letter-spacing:.5px}
.race-screen{position:fixed;inset:0;z-index:30;background:#101114;overflow:hidden;touch-action:none}.race-screen canvas{width:100%;height:100%;display:block}.race-hud{position:absolute;inset:0;pointer-events:none;padding:25px 35px;background:linear-gradient(180deg,#0009,transparent 25%,transparent 70%,#0009)}.hud-top{display:flex;justify-content:space-between;align-items:start}.hud-brand{font:900 italic 22px 'Barlow Condensed'}.hud-brand span{color:var(--red)}.hud-brand small,.hud-location small{display:block;font:700 8px Barlow;letter-spacing:2px;color:#ddd;margin-top:3px}.hud-location{text-align:center;font:800 italic 18px 'Barlow Condensed';letter-spacing:1px}.exit-race{pointer-events:auto;color:#fff;background:#161719bb;border:1px solid #ffffff55;padding:10px 12px;font-size:10px;font-weight:800;letter-spacing:1px}.hud-data{display:flex;gap:25px;margin-top:35px}.hud-box small,.boost-panel small{display:block;font-size:9px;letter-spacing:1.5px;color:#ddd;font-weight:800}.hud-box strong{font:900 italic 40px/.95 'Barlow Condensed'}.hud-box strong em{font-size:18px;color:#aaa}.hud-box .hud-time{font-size:26px}.race-message{position:absolute;top:38%;left:50%;transform:translate(-50%,-50%);font:900 italic 80px 'Barlow Condensed';color:white;text-shadow:0 3px 20px #000;opacity:0;transition:opacity .2s}.race-message.show{opacity:1}.hud-bottom{position:absolute;bottom:50px;left:35px;right:35px;display:flex;justify-content:space-between;align-items:end}.boost-panel{width:200px}.boost-panel small span{float:right;color:#aaa}.boost-track{height:8px;background:#ffffff55;margin-top:9px;transform:skew(-20deg)}.boost-track i{height:100%;display:block;width:0;background:var(--red)}.boost-panel p{font-size:8px;letter-spacing:1px;font-weight:800;color:#ccc}.speed-panel strong{font:900 italic 64px/.8 'Barlow Condensed'}.speed-panel span{font-size:10px;font-weight:800;letter-spacing:1px}.control-tip{position:absolute;bottom:16px;left:35px;font-size:9px;color:#ddd;font-weight:800;letter-spacing:1px}.control-tip span{margin-left:17px}.touch-controls{display:none}.result-panel{width:min(480px,100%);padding:40px;background:#1b1c1f;border:1px solid #414246}.result-panel h2{font:900 italic 54px/.9 'Barlow Condensed';margin:22px 0 15px}.result-panel p{color:#aaa;line-height:1.5}.result-actions{display:flex;gap:10px;margin-top:25px}.secondary-button{width:100%;border:1px solid #555;background:transparent;color:#fff;font:800 italic 15px 'Barlow Condensed'}
@media(max-width:1100px){.sidebar{width:165px}.content{padding-left:25px;padding-right:25px}.topbar{padding:0 25px}.dashboard{grid-template-columns:minmax(0,1fr) 280px}.setup{padding:20px 17px}.hero{height:330px}.hero h2{font-size:55px}}@media(max-width:800px){.sidebar{width:65px;padding:25px 10px}.brand>span:nth-child(2),.side-label,.nav-item:not(.active) .nav-arrow,.nav-arrow,.side-bottom{display:none}.brand-mark{margin:0 auto}.nav{margin-top:55px}.nav-item{font-size:0;justify-content:center;padding:14px}.nav-item.active{padding-left:12px}.nav-icon{font-size:20px}.dashboard{grid-template-columns:1fr}.setup{display:grid;grid-template-columns:1fr 1fr;gap:0 20px}.setup-top,.setup-line,.race-meta,.start-button,.setup-foot{grid-column:1/-1}.car-section{border:0;padding:0}.hero{height:340px}.modal-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:540px){.sidebar{display:none}.topbar{height:55px;padding:0 16px}.edition,.divider,.profile-icon{display:none}.content{padding:24px 15px 0}.page-heading h1{font-size:36px}.page-heading p{font-size:11px}.heading-index{display:none}.hero{height:300px}.hero-content{left:20px;top:24px}.hero h2{font-size:49px}.hero-bottom{margin-top:25px}.hero-tag{display:none}.location-grid{gap:6px}.location-card{height:100px}.location-info{left:8px;bottom:8px}.location-info strong{font-size:18px}.text-button{font-size:8px}.setup{display:block}.car-section{border-top:1px solid #343539;padding-top:17px}.modal-panel{padding:20px}.modal-header h2{font-size:30px}.modal-grid{grid-template-columns:repeat(2,1fr)}.choice{min-height:75px;padding:12px}.choice strong{font-size:17px}.race-hud{padding:15px}.hud-data{margin-top:25px;gap:14px}.hud-box strong{font-size:32px}.hud-bottom{bottom:105px;left:15px;right:15px}.boost-panel{width:150px}.speed-panel strong{font-size:48px}.control-tip{display:none}.touch-controls{position:absolute;bottom:15px;left:15px;right:15px;display:flex;justify-content:space-between;pointer-events:auto}.touch-controls>div{display:flex;gap:6px}.touch-controls button{border:1px solid #ffffff66;background:#171819aa;color:white;min-width:48px;height:52px;font-weight:800;font-size:10px;touch-action:none}.touch-controls .touch-boost{background:#c7372fdc}.hud-location{display:none}.race-message{font-size:60px}}
@media(pointer:coarse) and (min-width:541px){.touch-controls{position:absolute;bottom:15px;left:20px;right:20px;display:flex;justify-content:space-between}.touch-controls>div{display:flex;gap:8px}.touch-controls button{border:1px solid #ffffff66;background:#171819aa;color:#fff;width:60px;height:55px;font-weight:800;touch-action:none}.touch-controls .touch-boost{background:#c7372fdc}.hud-bottom{bottom:90px}.control-tip{display:none}}

const locations = [
  {name:'Tokyo',country:'Japan',flag:'🇯🇵',image:'tokyo',palette:['#de7893','#554e75','#283e52']},
  {name:'London',country:'United Kingdom',flag:'🇬🇧',image:'london',palette:['#879aa8','#667989','#33424b']},
  {name:'Los Angeles',country:'America',flag:'🇺🇸',image:'la',palette:['#e8a479','#987c8a','#494b62']},
  {name:'Mexico City',country:'Mexico',flag:'🇲🇽',palette:['#e7aa7a','#b37b70','#5a535a']},
  {name:'Budapest',country:'Hungary',flag:'🇭🇺',palette:['#dab5a0','#8c8690','#485360']},
  {name:'Nürburgring',country:'Germany',flag:'🇩🇪',palette:['#9caab5','#788c87','#43544d']},
  {name:'Victoria Falls',country:'Zimbabwe',flag:'🇿🇼',palette:['#e4b782','#a29b7b','#4a665a']},
  {name:'Lagos',country:'Nigeria',flag:'🇳🇬',palette:['#e5a678','#ad8874','#58666a']},
  {name:'Paris',country:'France',flag:'🇫🇷',palette:['#d4a3a2','#918696','#535a6b']},
  {name:'Dubai',country:'UAE',flag:'🇦🇪',palette:['#ecc18c','#b7a296','#6a6b70']},
  {name:'Rome',country:'Italy',flag:'🇮🇹',palette:['#edb68d','#b38b7e','#6d6060']},
  {name:'Sydney',country:'Australia',flag:'🇦🇺',palette:['#8cb7c5','#7497a0','#50696f']},
  {name:'Rio',country:'Brazil',flag:'🇧🇷',palette:['#edb68b','#98a3a0','#4b746c']}
];
const cars = [
  ['Bugatti Chiron','Supercars',95,78,'#3b83cd'],['Lamborghini Aventador SVJ','Supercars',93,82,'#e5bd31'],['Ferrari LaFerrari','Supercars',94,85,'#ef4235'],['McLaren P1','Supercars',92,88,'#ed8c31'],['Koenigsegg Jesko','Supercars',99,80,'#dedede'],['Pagani Huayra','Supercars',93,86,'#a9aeb5'],['Ferrari SF90','Supercars',94,90,'#df332f'],['Ford GT','Supercars',91,87,'#417dc3'],
  ['Nissan Skyline R34','Japanese cars',84,91,'#609ad3'],['Toyota Supra MK4','Japanese cars',85,87,'#ed9a2c'],['Mazda RX-7','Japanese cars',82,94,'#e9c74a'],['Honda NSX','Japanese cars',83,93,'#dc4641'],['Nissan Skyline R32','Japanese cars',81,89,'#babfc5'],['Mitsubishi Evo 9','Japanese cars',80,93,'#d7d9d9'],['Subaru Impreza 22B','Japanese cars',82,92,'#416ec8'],
  ['Ferrari F40','Classic cars',87,82,'#d83b36'],['Lamborghini Countach','Classic cars',85,78,'#efefea'],['Porsche 911 Carrera RS','Classic cars',81,90,'#eee8d7'],['Aston Martin DB5','Classic cars',76,80,'#aab0ad'],['Ford Escort RS Cosworth','Classic cars',78,89,'#557cc5']
].map(([name,category,speed,handling,color])=>({name,category,speed,handling,color}));
let selectedLocation=locations[0], selectedCar=cars[0], game=null, modalType='locations', filter='All';
const $=id=>document.getElementById(id);
function renderSetup(){
  $('selectedLocation').textContent=selectedLocation.name.toUpperCase(); $('selectedCountry').textContent=selectedLocation.country.toUpperCase(); $('selectedFlag').textContent=selectedLocation.flag;
  $('selectedCar').textContent=selectedCar.name.toUpperCase(); $('selectedClass').textContent=selectedCar.category==='Supercars'?'SUPERCAR':selectedCar.category.toUpperCase().replace(/S$/,'');
  $('speedStat').textContent=selectedCar.speed; $('handlingStat').textContent=selectedCar.handling; $('speedBar').style.width=selectedCar.speed+'%'; $('handlingBar').style.width=selectedCar.handling+'%';
  $('featuredLocations').innerHTML=locations.slice(0,3).map((l,i)=>`<button class="location-card ${selectedLocation===l?'active':''}" data-featured="${i}" aria-label="Select ${l.name}"><img src="assets/${l.image}.jpg" alt=""><span class="location-info"><small>${l.flag} ${l.country.toUpperCase()}</small><strong>${l.name.toUpperCase()}</strong></span>${selectedLocation===l?'<span class="location-check">✓</span>':''}</button>`).join('');
  document.querySelectorAll('[data-featured]').forEach(el=>el.onclick=()=>{selectedLocation=locations[+el.dataset.featured];renderSetup()});
}
function openModal(type){modalType=type;filter='All';$('selectionModal').classList.remove('hidden');$('crumb').textContent=type==='garage'?'GARAGE':'LOCATIONS';document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===type));renderModal()}
function closeModal(){$('selectionModal').classList.add('hidden');$('crumb').textContent='RACE';document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view==='home'))}
function renderModal(){
  const garage=modalType==='garage'; $('modalTitle').innerHTML=garage?'CHOOSE YOUR <em>RIDE</em>':'CHOOSE YOUR <em>LOCATION</em>'; $('modalSubtitle').textContent=garage?'20 icons. One driver. Find the car that fits your style.':'The world is waiting. Pick your next destination.';
  let filters=garage?['All','Supercars','Japanese cars','Classic cars']:['All'];
  $('modalFilters').innerHTML=filters.map(f=>`<button class="filter ${f===filter?'active':''}" data-filter="${f}">${f.toUpperCase()} ${f==='All'?(garage?'20':'13'):''}</button>`).join('');
  $('modalFilters').querySelectorAll('button').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderModal()});
  if(garage){$('modalGrid').innerHTML=cars.map((c,i)=>({c,i})).filter(({c})=>filter==='All'||c.category===filter).map(({c,i})=>`<button class="choice ${c===selectedCar?'selected':''}" data-car="${i}"><small>${c.category.toUpperCase()}</small><strong>${c.name.toUpperCase()}</strong><span class="choice-stats">SPD ${c.speed} &nbsp; / &nbsp; HND ${c.handling}</span></button>`).join('');$('modalGrid').querySelectorAll('[data-car]').forEach(b=>b.onclick=()=>{selectedCar=cars[+b.dataset.car];renderSetup();closeModal()})}
  else{$('modalGrid').innerHTML=locations.map((l,i)=>`<button class="choice ${l===selectedLocation?'selected':''}" data-location="${i}"><span class="choice-flag">${l.flag}</span><small>${l.country.toUpperCase()}</small><strong>${l.name.toUpperCase()}</strong></button>`).join('');$('modalGrid').querySelectorAll('[data-location]').forEach(b=>b.onclick=()=>{selectedLocation=locations[+b.dataset.location];renderSetup();closeModal()})}
}
$('allLocations').onclick=$('changeLocation').onclick=()=>openModal('locations');$('changeCar').onclick=()=>openModal('garage');$('closeModal').onclick=closeModal;$('selectionModal').onclick=e=>{if(e.target===$('selectionModal'))closeModal()};document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>b.dataset.view==='home'?closeModal():openModal(b.dataset.view));
function formatTime(seconds){seconds=Math.max(0,Math.floor(seconds||0));return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')}
function updateHud(state){$('hudSpeed').textContent=Math.round(state.speed||0);$('hudPosition').textContent=state.place||state.position||11;$('hudProgress').innerHTML=Math.floor((state.progress||0)*100)+'<em>%</em>';$('hudTime').textContent=formatTime(state.time);$('boostBar').style.width=Math.max(0,Math.min(100,state.overdrive||0))+'%';$('boostBar').style.background=state.boostActive?'#fff':'#f54235'}
function startRace(){closeModal();$('resultModal').classList.add('hidden');$('raceScreen').classList.remove('hidden');$('hudLocation').innerHTML=selectedLocation.name.toUpperCase()+' <small>WORLD SPRINT</small>';if(game)game.stop();game=new window.OverdriveGame($('raceCanvas'),{location:selectedLocation,car:selectedCar,onUpdate:updateHud,onFinish:finishRace});game.start();$('raceMessage').textContent='GO!';$('raceMessage').classList.add('show');setTimeout(()=>$('raceMessage').classList.remove('show'),1200)}
function finishRace(result){$('resultTitle').textContent=(result.place||result.position)===1?'YOU WIN.':'FINISH LINE.';const place=result.place||result.position||11;$('resultText').textContent=`You finished ${place}${place===1?'st':place===2?'nd':place===3?'rd':'th'} out of 11 in ${selectedLocation.name}. Time: ${formatTime(result.time)}. Ready to go again?`;$('resultModal').classList.remove('hidden')}
function exitRace(){if(game)game.stop();game=null;$('raceScreen').classList.add('hidden');$('resultModal').classList.add('hidden')}
$('startRace').onclick=startRace;$('exitRace').onclick=exitRace;$('backToMenu').onclick=exitRace;$('raceAgain').onclick=startRace;
const keyMap={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',' ':'boost',Shift:'boost'};
window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('resultModal').classList.contains('hidden'))exitRace();else if(!$('raceScreen').classList.contains('hidden'))exitRace();else closeModal()}if(game&&keyMap[e.key]){e.preventDefault();game.setInput(keyMap[e.key],true)}});window.addEventListener('keyup',e=>{if(game&&keyMap[e.key]){e.preventDefault();game.setInput(keyMap[e.key],false)}});window.addEventListener('blur',()=>{if(game)['left','right','up','down','boost'].forEach(k=>game.setInput(k,false))});
document.querySelectorAll('[data-key]').forEach(b=>{const key=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);if(game)game.setInput(key,true)});['pointerup','pointercancel','lostpointercapture'].forEach(event=>b.addEventListener(event,()=>{if(game)game.setInput(key,false)}))});
renderSetup();

