173:     _resize() {
174:       const rect = this.canvas.getBoundingClientRect();
175:       const w = Math.max(1, rect.width || this.canvas.clientWidth || 800);
176:       const h = Math.max(1, rect.height || this.canvas.clientHeight || 450);
